const { z } = require("zod");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const schema = z.record(z.string(), z.string());
const input = { key: "value" };
Object.defineProperty(input, "hidden", { value: 123, enumerable: false });
const r = schema.safeParse(input);
if (!r.success) {
  const paths = r.error.issues.map((i) => i.path.join("."));
  if (paths.length === 1 && paths[0] === "hidden") symptom("z.record validated the non-enumerable property hidden and rejected the input");
  broken("unexpected issues: " + JSON.stringify(r.error.issues));
}
if (JSON.stringify(r.data) !== "{\"key\":\"value\"}" || Object.prototype.hasOwnProperty.call(r.data, "hidden")) broken("unexpected data: " + JSON.stringify(r.data));
const bad = schema.safeParse({ key: "value", bad: 1 });
if (bad.success) broken("z.record accepted an enumerable invalid value");
console.log("OK: z.record skips the non-enumerable property hidden");

